import{_ as a,o as n,c as e,S as l}from"./chunks/framework.D1Ss-Xl7.js";const u=JSON.parse('{"title":"亚马逊S3服务简单介绍","description":"","frontmatter":{"title":"亚马逊S3服务简单介绍","date":"2019-01-23 21:20","comments":true,"archives":2019,"tags":["AWS"]},"headers":[],"relativePath":"posts/2019-01-23-aws-s3/index.md","filePath":"posts/2019/2019-01-23-AWS-S3.md"}'),o={name:"posts/2019-01-23-aws-s3/index.md"};function p(r,s,t,c,i,d){return n(),e("div",null,[...s[0]||(s[0]=[l(`<p>最近在做后端的开发，需要一些二进制数据保存在服务器云端。团队决定调查 AWS 的 S3 服务是否满足需求，所以就做了一些调查工作。不过也遇到很多坑的地方。所以记录下来，防止以后再遇到。</p><h2 id="基本需求" tabindex="-1">基本需求 <a class="header-anchor" href="#基本需求" aria-label="Permalink to &quot;基本需求&quot;">​</a></h2><p>需要云服务有稳定性保证，并且可以批量上传文件。可以设置上传和下载链接的有效期。</p><h2 id="aws-试用" tabindex="-1">AWS 试用 <a class="header-anchor" href="#aws-试用" aria-label="Permalink to &quot;AWS 试用&quot;">​</a></h2><p>AWS 提供免费试用，但是注册的时候需要填写信用卡信息。确实有点不安，万一不小心被收费了就不好了。</p><h2 id="生成上传凭证" tabindex="-1">生成上传凭证 <a class="header-anchor" href="#生成上传凭证" aria-label="Permalink to &quot;生成上传凭证&quot;">​</a></h2><p>我使用的是 AWS 的 <a href="https://docs.aws.amazon.com/AWSJavaScriptSDK/latest/AWS/S3.html" target="_blank" rel="noreferrer">JavaScript SDK</a>。使用 <code>createPresignedPost</code> API 可以创建用于上传的凭证。这个凭证是根据用户的 AccessId，AccessKey 和 Policy 策略等计算生成的，并没有和 AWS 服务器直接进行交互。所以不用担心这个接口和 AWS 直接的流量费用问题。</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> params </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> {</span></span>
<span class="line"><span style="color:#24292E;">  Bucket: </span><span style="color:#032F62;">&#39;bucket&#39;</span><span style="color:#24292E;">,</span></span>
<span class="line"><span style="color:#24292E;">  Conditions: [[</span><span style="color:#032F62;">&#39;starts-with&#39;</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&#39;$key&#39;</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&#39;path/to/uploads/&#39;</span><span style="color:#24292E;">]]</span></span>
<span class="line"><span style="color:#24292E;">};</span></span>
<span class="line"><span style="color:#24292E;">s3.</span><span style="color:#6F42C1;">createPresignedPost</span><span style="color:#24292E;">(params, </span><span style="color:#D73A49;">function</span><span style="color:#24292E;"> (</span><span style="color:#E36209;">err</span><span style="color:#24292E;">, </span><span style="color:#E36209;">data</span><span style="color:#24292E;">) {</span></span>
<span class="line"><span style="color:#D73A49;">  if</span><span style="color:#24292E;"> (err) {</span></span>
<span class="line"><span style="color:#24292E;">    console.</span><span style="color:#6F42C1;">error</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;Presigning post data encountered an error&#39;</span><span style="color:#24292E;">, err);</span></span>
<span class="line"><span style="color:#24292E;">  } </span><span style="color:#D73A49;">else</span><span style="color:#24292E;"> {</span></span>
<span class="line"><span style="color:#24292E;">    data.Fields.key </span><span style="color:#D73A49;">=</span><span style="color:#032F62;"> &#39;path/to/uploads/\${filename}&#39;</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#24292E;">    console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;The post data is&#39;</span><span style="color:#24292E;">, data);</span></span>
<span class="line"><span style="color:#24292E;">  }</span></span>
<span class="line"><span style="color:#24292E;">});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>官方提供的例子中，可以使用<code>starts-with</code>的方式来指定上传文件的 key 必须是以什么开头的，这样就可以指定上传的文件夹。很多文件也可以使用这一个上传凭证来完成上传。</p><h2 id="上传-policy-构造" tabindex="-1">上传 Policy 构造 <a class="header-anchor" href="#上传-policy-构造" aria-label="Permalink to &quot;上传 Policy 构造&quot;">​</a></h2><p>AWS 提供了一个详细文档说明如何构造合法的 Policy：<a href="https://docs.aws.amazon.com/AmazonS3/latest/API/sigv4-HTTPPOSTConstructPolicy.html" target="_blank" rel="noreferrer">Creating a POST Policy</a>。例如常见的需求就是在上传的时候添加 meta 信息声明文件的格式或者 MD5 值。 Policy 的 Conditions 数组里面可以添加<code>[&quot;starts-with&quot;, &quot;$x-amz-meta-md5checksum&quot;, &quot;&quot;]</code>。最后一个参数为空字符串代表可以上传任何数值。</p><h2 id="构造-post-表单" tabindex="-1">构造 POST 表单 <a class="header-anchor" href="#构造-post-表单" aria-label="Permalink to &quot;构造 POST 表单&quot;">​</a></h2><p>AWS 也有文档说明了如何构造一个<a href="https://docs.aws.amazon.com/AmazonS3/latest/API/sigv4-post-example.html" target="_blank" rel="noreferrer">上传的表单</a>。这个表单中最重要的是一句注释：<code>The elements after this will be ignored</code>。在 file 字段之后的所有信息都会被忽略掉，我测试的时候一直把<code>x-amz-meta-md5checksum</code>字段放在 file 字段之后导致上传一直报错。直到 Stack Overflow 上面有人解释了才恍然大悟。</p><h2 id="构造下载链接" tabindex="-1">构造下载链接 <a class="header-anchor" href="#构造下载链接" aria-label="Permalink to &quot;构造下载链接&quot;">​</a></h2><p>我们使用<code>getSignedUrl</code> API 来生成下载链接，下载链接也是根据自己的 AccessId 和 AccessKey 生成链接的凭证，也没有和 AWS 服务器直接进行交互。当请求文件的时候，AWS 再计算凭证是否有效。所以后端无需和 AWS 交互就可以返回客户端有效的 AWS 下载链接。针对需要返回实际文件的 API 接口，可以采用返回 302 的跳转链接来完成需求。示例代码如下：</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> params </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> { Bucket: </span><span style="color:#032F62;">&#39;bucket&#39;</span><span style="color:#24292E;">, Key: </span><span style="color:#032F62;">&#39;key&#39;</span><span style="color:#24292E;"> };</span></span>
<span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> url </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> s3.</span><span style="color:#6F42C1;">getSignedUrl</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;getObject&#39;</span><span style="color:#24292E;">, params);</span></span>
<span class="line"><span style="color:#24292E;">console.</span><span style="color:#6F42C1;">log</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;The URL is&#39;</span><span style="color:#24292E;">, url);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>可能有人会问，这个 API 也可以用来上传啊。但是这个 API 接口必须指定 key 值，这样我们就需要为每个文件来生成一个独立的上传 URL。这样太麻烦了。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>我们使用 pre-sign 的方式来生成 URL 主要是为了对客户端透明。虽然我们可以设置最小权限的 IAM User 给客户端，但是客户端很容易被逆向拿到敏感数据。这样难免会有风险，所以生成一个单纯的 URL 供客户端使用一定程度上保证了安全性也减少了客户端的复杂性。毕竟我也不想引入一个 AWS 的 SDK 进来。</p>`,19)])])}const h=a(o,[["render",p]]);export{u as __pageData,h as default};
